-- Mod-authored world wonder splash painting descriptions, ru_RU overlay.
-- Baseline in CivVAccess_WonderDescStrings_en_US.lua.
CivVAccess_Strings = CivVAccess_Strings or {}

CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_MISSING"] = "Для этого чуда нет описания."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_MOTHERLAND_STATUE"] =
    "Игра вышла без картины для этого чуда; изображения, которое можно было бы описать, нет."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_ALHAMBRA"] =
    "Из-под тени стройной каменной колонны открывается дворцовый двор с длинным зеркальным водоёмом, это Миртовый двор Альгамбры. Водоём убегает вдаль к аркадному портику из камня розового цвета, чьи арки отражаются в неподвижной воде. Сзади на фоне синего неба тёплым светом поднимается квадратная крепостная башня. Низкие подстриженные живые изгороди тянутся вдоль кромки воды, на переднем плане стоит растение в горшке, а вдоль освещённых солнцем дорожек небольшими группами беседуют люди в длинных халатах. Яркое послеполуденное солнце заливает двор, белея там, где падает на мощение. Под колоннадой лежит глубокая тень."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_ANGKOR_WAT"] =
    "На заднем плане поднимается группа ярусных серых каменных башен, по форме напоминающих закрытые бутоны лотоса, наполовину заслонённых пальмами под жарким бледным небом. На переднем плане - праздничное шествие: серый слон шагает сквозь плотную толпу, на его шее сидит погонщик, а на спине устроено сиденье под балдахином, затенённое высоким красно-оранжевым зонтом. Толпа теснится со всех сторон в белых, шафрановых и сливовых одеяниях; головы обмотаны тканью, плечи обнажены, и все лица обращены к слону, когда он проходит мимо. Сцена залита солнцем и пыльна, а камень холодного зелёно-серого тона выделяется на фоне тёплой кожи и ткани внизу."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_BIG_BEN"] =
    "Готическая часовая башня стоит ночью в конце Вестминстерского моста, её четырёхгранные часы светятся янтарём у самого верха. Над часами шпиль тает в глубоком синем небе. Длинный фасад лондонского Вестминстерского дворца уходит влево, окна и каменная кладка освещены тёплым золотом прожекторов. На его дальнем конце поднимаются увенчанные пинаклями башни. Мост пересекает передний план с рядом светящихся фонарных столбов. Несколько карет и фигур видны на мостовой маленькими и тёмными. Вся сцена написана в ночных синих тонах на фоне золота фонарей и освещённого камня."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_BOROBUDUR"] =
    "Ступенчатая пирамида из серого вулканического камня поднимается из джунглей, словно террасированный холм, её верхние ярусы опоясаны небольшими колоколообразными ступами. Вершину венчает ступа покрупнее. С нижних террас растут пальмы, и лес тесно обступает подножие Боробудура. На переднем плане вереница монахов в оранжевых и красных одеяниях восходит к храму по затенённой тропе сквозь джунгли, а в вышине по дымчатому небу разлетаются птицы. Палитра туманно-серо-зелёная, и одеяния - единственное сильное пятно цвета."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_BRANDENBURG_GATE"] =
    "Широкие классические врата из выветренного песчаника стоят в глубине оживлённой городской площади, поднятые на парных рядах тяжёлых колонн и увенчанные квадригой, бронзовой статуей колесницы с четвёркой коней, которая темнеет на фоне бледного пасмурного неба. Более низкое колоннадное крыло отходит вправо к окружающим каменным зданиям. Площадь перед ними - это Берлин девятнадцатого века: запряжённые лошадьми кареты катятся по брусчатке, всадники и толпы в длинных тёмных пальто и цилиндрах, а слева поднимается фонарный столб. Цвета сдержанные, серые и коричневые, а свет ровный и рассеянный."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_BROADWAY"] =
    "Театральный квартал ночью в начале двадцатого века, улица мокрая от дождя и блестит отражённым светом. Освещённые навесы и вывески теснятся по обеим сторонам Бродвея, белые и красные лампочки складываются в названия спектаклей. В центре квартала светится один длинный яркий фасад театра. Толпы в тёмных пальто и шляпах заполняют тротуары и выплёскиваются на улицу среди нескольких старых автомобилей, и все кажутся маленькими на фоне высоких тёмных конторских зданий, что поднимаются в ночное небо. Палитра глубокого сине-чёрного цвета, разбитая лужицами тёплого белого, красного и жёлтого электрического света."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_CN_TOWER"] =
    "Тонкая бетонная игла поднимается в центре панорамы Торонто, утолщаясь в округлую смотровую капсулу у самого верха и сужаясь дальше в антенный шпиль. Вокруг неё расходятся грозовые тучи, и сквозь просвет за башней проливаются столбы солнечного света, окутывая дымкой конторские здания по обе стороны. На переднем плане заглублённая автомагистраль струится потоком машин, фары и красные задние огни светятся в мутной мгле между бетонными насыпями. Вся сцена стально-серая и золотая. Город наполовину в грозовой тени, наполовину в пробивающемся свете."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_CHICHEN_ITZA"] =
    "Ступенчатая пирамида, Эль-Кастильо, стоит в центре под пылающим оранжевым небом, девять квадратных ярусов поднимаются к небольшому храму на вершине. По её грани прямо вверх идёт широкая лестница. У левого края поднимается второй ярусный храм, и дым стелется по солнцу, что висит низко и красно. Площадь внизу заполнена толпой майя, большинство из них обращены спиной: обнажённые плечи, головные уборы из перьев, поднятые посохи и копья. Группа воинов стоит на каменном помосте справа. Всё пропитано ржавым и янтарным светом сумерек. Толпа превращается в тёмные силуэты на фоне светящегося камня."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_CRISTO_REDENTOR"] =
    "Колоссальный Христос из бледного камня, увиденный сзади и сверху, стоит на пьедестале на вершине горы, раскинув руки над заливом внизу. Его одетая в одеяние спина и распростёртые руки заполняют ближний план, голова слегка склонена вперёд. Дальше и далеко внизу Рио-де-Жанейро раскинулся вокруг воды белыми россыпями зданий, а из залива среди зелёных островов и стоящих на якоре кораблей поднимается округлый горб горы Сахарная Голова. Дымка смягчает даль, оставляя город и море в бледных синих и серых тонах, тогда как плечи статуи ловят дневной свет."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_COLOSSUS"] =
    "Бронзовый исполин стоит вдали, у скалистого входа в гавань, с поднятой рукой, наполовину растворившись в золотистой дымке. На фоне неба цвета латуни это скорее силуэт, чем статуя. Передний план принадлежит морю: небольшая парусная лодка кренится к смотрящему под единственным широким парусом, на корме видны двое или трое моряков. По гавани разбросаны другие паруса. У самой воды справа тянутся низкие скалы, и вода несёт тот же тёплый золотой оттенок, что и небо. Вся картина выдержана в одном цвете, в янтарном свете и дымке. Колосс светится сквозь неё, словно фигура во сне."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_MOSQUE_OF_DJENNE"] =
    "Длинная глинобитная стена с башнями и пиками тянется через весь задний план, сложенная из глиняного кирпича глубокого красно-коричневого цвета. Её грани щетинятся торонами, рядами деревянных балок, торчащих из стен, словно шипы. Небо за нею густо затянуто оранжевой пылью и дымом, а солнце потеряно в дымке. Весь передний план - это базарный день: навесы и тенты в красном и белом, животные среди прилавков и плотная толпа в ярких одеяниях, снующая между ними. Зной и пыль объединяют сцену, и всё написано в оранжевых, ржавых и коричневых тонах."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_EIFFEL_TOWER"] =
    "Тёмная железная решётка из опор и зарешеченных площадок заполняет верхний левый угол кадра, так близко, что вершина срезана краем картины. Под нею разворачивается сцена послеполуденного отдыха Прекрасной эпохи на траве: компании в длинных белых платьях и тёмных костюмах устроили пикник на широкой зелёной лужайке, вокруг них разложены зонтики, шляпы от солнца и корзины. В центре стоит женщина в белом. За лужайкой струится Сена, а светлый камень Парижа тянется по дальнему берегу под мягким серым небом. Палитра выдержана в холодных зелёных и серых тонах. Белые платья ловят тот скудный свет, что здесь есть."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_FORBIDDEN_PALACE"] =
    "Дворцовые залы с покатыми золотисто-черепичными крышами и глубокими красными стенами стоят за обширным мощёным двором, увиденные с приподнятой мраморной террасы на переднем плане. Тёмная статуя льва-стража припала к балюстраде террасы слева, а вдоль лестницы стоят фигуры в одеяниях. Внизу, во дворе, перед центральным залом выстроены в плотном строю ряды солдат, которых подавляет окружающая их архитектура. Бледное солнце висит в туманном янтарном небе, и вся сцена омыта пыльным золотом на фоне красноты стен."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GLOBE_THEATER"] =
    "Круглый деревянный театр, увиденный с его собственной сцены посреди представления. Три яруса галерейных балконов огибают центральный двор, и каждый поручень забит зрителями. На открытом полу внизу теснятся стоячие зрители, бледное море лиц. На сцене актёр в тёмном дублете играет сцену, обращаясь к двум женщинам в длинных платьях, одна из которых жестикулирует вытянутой рукой. Расписной навес кровли вдаётся в кадр в верхнем правом углу на резном столбе. Мягкий дневной свет падает с открытого неба над двором. Дерево тёплого кремового и коричневого цвета, а толпа намечена бледно вокруг более чётких фигур на сцене."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GREAT_FIREWALL"] =
    "Абстрактная цифровая сцена без единого здания, тёмное киберпространство, переданное в зелёных и чёрных тонах. Широкие изогнутые поверхности проносятся через кадр, словно валы из данных, их грани выложены светящимися зелёными двоичными цифрами, а вдоль них тянутся сияющие следы, будто потоки машин на ночном шоссе. Призрачные экраны и сетки парят во мгле наверху, намекая на схемы и слежку. Весь образ выглядит как внутренний мир компьютера, фосфорно-зелёный свет на чёрном."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GREAT_LIBRARY"] =
    "Монументальный классический зал выходит на залитую солнцем площадь, между колоннами его длинной колоннады вывешены высокие красные стяги. Над колоннами тянется резной фриз, а к мостовой спускаются широкие ступени. Площадь увидена из затенённого портика на переднем плане: слева поднимается колонна, справа на постаменте сидит каменный сфинкс, а вдали виднеется белый купол. Учёные и горожане в тогах и цветных одеяниях собираются на ступенях и по всей площади, большинство стоят по двое и по трое в беседе, тогда как одна фигура сидит в одиночестве со свитком. Камень тёплого кремового цвета в солнечном свете под синим небом, перечёркнутым полосами облаков, а стяги - самый яркий красный в этой сцене."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GREAT_LIGHTHOUSE"] =
    "Высокая бледная башня из поставленных друг на друга ярусов стоит вдали справа, освещённая разрывом в буре, её маяк светится на вершине. Остальная часть картины - бурное море: вереница древних галер под красно-белыми полосатыми прямыми парусами пробивается сквозь тяжёлые серо-зелёные валы к свету, носы их высоко изогнуты. Брызги вспыхивают белизной о борта. Тёмные грозовые тучи давят на всю сцену, и небо открывается лишь вокруг башни, словно корабли спешат к ней. Паруса несут единственный тёплый цвет в картине из аспидно-серого, пены и дождя."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_GREAT_WALL"] =
    "Широкий каменный вал бежит от нижнего края кадра прямо вверх и через горы, его зубчатые парапеты взбираются по гребням хребтов, пока стена не съёживается до нити на самых дальних вершинах. У первого подъёма стоит квадратная двухэтажная сторожевая башня с арочными окнами и небольшим крытым павильоном наверху. Путь стены изгибается сквозь неё. Горы складчаты и зелены, поросшие кустарником склоны спадают в дымку, долина за долиной. Нигде на стене не видно ни одной фигуры. Свет холоден и ясен, серый камень на фоне глубокой зелени под бледным небом."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_HAGIA_SOPHIA"] =
    "Огромная купольная базилика венчает панораму города в час золотого заката, её широкий центральный купол поднимается над нагромождением укреплённых контрфорсами стен и полукуполов. Четыре стройных минарета стоят по углам: здание изображено как мечеть, которой собор Святой Софии стал позднее. Вокруг него крыши Стамбула скатываются под гору в коричневых и серых тонах, прерываемые деревьями, малыми куполами и далёкими башнями, растворяющимися в дымке. Блик воды и низкие холмы замыкают даль слева. Всё лежит под тёплым янтарным небом, и силуэт купола выделяется тёмным золотом на фоне света."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_HANGING_GARDEN"] =
    "Садовый двор лежит внутри стен из тёплого песчаника с арками. Пальмы поднимаются над дорожками, и зелень свешивается с каждой арки и каждого уступа. Фигуры в длинных одеяниях прогуливаются и беседуют по двое и по трое вдоль тенистых тропинок среди клумб и небольших деревьев. Сквозь центральную арку и над стеной белый дворцовый город взбирается на холм ярусами, сияя вдали, словно венец этих Висячих садов. Всё стоит под ярким солнцем, густая зелёная листва на фоне золотистого камня и бледного неба."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_HIMEJI_CASTLE"] =
    "Белая башня замка Химэдзи поднимается с лесистого холма в верхней части кадра, ярус за ярусом светлых стен под изогнутыми серыми крышами. Меньшие белые башенки теснятся ниже неё среди деревьев. Дорога к замку проходит через деревню с тёмными черепичными крышами, и ворота в красной раме перекрывают путь на среднем плане. Конные самураи едут к нему через передний план, высокие красные знамёна торчат у них за спинами. Пешие воины в доспехах ждут у домов справа. День мягкий и пасмурный, и вся сцена выдержана в зелёных и серых тонах вокруг белой башни. Знамёна - самый резкий красный цвет в сцене."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_HUBBLE"] =
    'Длинный серебристый цилиндр, обёрнутый панелями из фольги, плывёт на орбите, его откидная крышка апертуры открыта на ближнем конце, обнажая тёмное жерло оптики. Плоские солнечные батареи в медно-золотых рамах раскинуты по бокам, и астронавт в скафандре работает у борта телескопа "Хаббл", малый рядом с прибором. Часть пристыкованного космического корабля заходит в правый нижний угол кадра. За всем этим Земля заполняет картину, изгиб синего океана и белых облаков, уходящий в чёрный космос. Палитра серебристая и золотая на фоне синевы Земли.'
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_KREMLIN"] =
    "Снег падает над Красной площадью, где стена крепости из тёмно-красного кирпича тянется вдоль правого края под тяжёлым серым зимним небом. Красный флаг развевается над приземистым ступенчатым объёмом Мавзолея Ленина, поставленного у стены, а дальше высокая башня поднимается в мглу, её шпиль имеет форму крутого шатра. Толпы в длинных тёмных пальто и меховых шапках тянутся через заснеженную площадь медленной чередой, отдельные фигуры бредут по переднему плану спиной к зрителю. Картина почти монохромна, белый снег и угольно-серый цвет, и единственный красный в ней - это кирпич и флаг."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_LEANING_TOWER"] =
    "Круглая белая колокольня поднимается с зелёной лужайки, опоясанная этаж за этажом открытыми мраморными аркадами и явно кренясь вправо. Пизанская башня сияет на фоне тёмного грозового неба. Бледный бок Пизанского собора стоит у правого края кадра, а более низкие городские дома цвета охры замыкают зелень слева. Горожане и монахи в длинных коричневых и красных одеяниях пересекают лужайку нестройными процессиями, крошечные под башней. Свет театрален: разрыв в облаках высвечивает белый мрамор, в то время как небо за ним остаётся почти чёрным."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_LOUVRE"] =
    "Серый каменный дворец простирается по заднему плану, высокий центральный павильон с резным орнаментом и крутыми шиферными мансардными крышами, с крыльями, расходящимися в обе стороны. Художники показывают Лувр в его дни как королевский дворец, задолго до стеклянной пирамиды современного музея. Впереди лежат регулярные сады: плоские лужайки, пересечённые гравийными дорожками, молодые деревья и небольшой фонтан, бьющий водой слева. Гуляющие в нарядах девятнадцатого века рассеяны по аллеям, женщины в длинных белых платьях и мужчины в тёмных сюртуках и цилиндрах. Пара останавливается вместе справа. День мягкий и жемчужный. Всё выдержано в сером камне и приглушённой зелени под бледным небом."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_MACHU_PICHU"] =
    "Каменный город Мачу-Пикчу сидит в высоком горном седле, земледельческие террасы поднимаются ступенями по склону к группам зданий с фронтонами под соломенными крышами. За ним крутой пик Уайна-Пикчу взбирается в облака. Туман висит над окрестными хребтами, и долина обрывается в тень внизу. На тропе переднего плана небольшой отряд с вьючными ламами пробирается вверх к городским воротам, крошечный на фоне террас. Свет проникает бледными полосами сквозь непогоду, выхватывая тёплую коричневую каменную кладку из зелени и серости Анд."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_MAUSOLEUM_HALICARNASSUS"] =
    "Массивный квадратный подиум из белого мрамора, опоясанный скульптурными фризами, поднимается к кольцу колонн в верхней части кадра. Галикарнасский мавзолей возвышается над площадью, где статуи стоят на высоких столбах, среди них фигура в доспехах и всадник. Тёмные кипарисы высажены между мощёными площадками. Фигуры в белых и красных одеяниях собираются внизу, крошечные на фоне памятника. День яркий и ясный. Белый мрамор и громады белых облаков стоят на фоне глубокого синего неба."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_NEUSCHWANSTEIN"] =
    "Бледное видение замка Нойшванштайн стоит на лесистом хребте, белые стены и сгрудившиеся башни, наполовину растворённые в падающем снеге в верхнем левом углу кадра. Передний план - это дорога к нему: тёмная закрытая карета ждёт на повороте, пока всадники тянутся вверх по склону, взрывая снег на дороге. Запорошённые снегом ели обрамляют путь и смыкаются над долиной внизу. Картина повсюду зимняя, серая и белая. Всадники и карета - единственные тёмные силуэты на её фоне."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_NOTRE_DAME"] =
    "Готический собор вздымается над средневековым Парижем, вид сверху; его две квадратные башни, центральный шпиль и длинный неф с контрфорсами стоят высоко над всеми окрестными крышами. Город тесно подступает к его стенам плотным переплетением домов с фронтонами и дымящих труб, а на переднем плане Сена изгибается мимо набережных и небольших лодок. Небо тяжёлое и серое, но сквозь облака пробиваются снопы солнечного света и падают прямо на собор, окрашивая его камень в золото, тогда как город остаётся в свинцовой тени. Горизонт за крышами тает плоской бледной полосой."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_ORACLE"] =
    "Круглый храм с колоннадой под каменным куполом, толос, стоит на морском утёсе у самого края скалистого мыса, а под ним сквозь обрыв открывается естественная арка. Художники поместили святилище на побережье, а не на склоне Дельфийской горы. Тропа вьётся к нему мимо приливных луж и стоячих скал. На переднем плане паломники в красных, синих и белых одеяниях небольшими группами движутся по тропе, обрамлённые тёмными соснами, склонившимися с обеих сторон. Прохладный ранний вечер, бледное лунное небо и серо-зелёное море вокруг тёплого камня святилища."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PARTHENON"] =
    "Длинный дорический храм стоит целиком во всю верхнюю часть кадра, его колоннада несёт скульптурный и расписанный фронтон. Мрамор отливает тёплым золотом под небом, по которому катятся серые тучи. От храма вниз через заросли низкого зелёного кустарника спускаются широкие ступени, а слева на постаментах подняты бронзовые статуи. По ступеням сходит процессия греков в багряных плащах, и в центре одинокий гоплит обращён лицом к смотрящему, в шлеме с гребнем и круглым щитом на руке. Красный цвет плащей пылает на фоне камня, а свет несёт тяжёлую яркость дня перед грозой."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PENTAGON"] =
    "Вид сверху на пятиугольное здание штаба, его концентрические пятиугольные кольца из бледного бетона и тёмной кровли ступенями уходят внутрь к зелёному внутреннему двору в центре. Дороги и парковки опоясывают здание, а за ними простираются газоны и тронутые осенью деревья. Позади течёт Потомак, через который перекинуты мосты. На дальнем берегу столица лежит в дымке, белый обелиск монумента Вашингтона и купол Капитолия кажутся маленькими на горизонте. День простой и серый; ничто в сцене не выделяется, кроме формы самого здания."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PETRA"] =
    "Смотрящий стоит внутри Сика, узкого каньонного прохода, между розово-красными скальными стенами, что вздымаются в тени по обе стороны кадра. Сквозь проём видна залитая полным солнцем Эль-Хазне, Сокровищница, фасад, высеченный прямо в скале. Два его яруса классических колонн и фронтонов поднимаются в розовом песчанике, а в центре верхнего уровня стоит круглый павильон. Путники движутся к нему по песчаному дну каньона: на ближнем переднем плане двое всадников покачиваются на верблюдах, а позади идут фигуры в одеяниях. Картина вся в тёплых красных и тенистых коричневых тонах, и резной фасад светится в конце тёмного прохода."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PORCELAIN_TOWER"] =
    "Высокая пагода поднимается над храмовым садом, ярус за ярусом тёмных изогнутых карнизов на стройном теле. Она стоит над черепичными крышами залов у её подножия. Сад расстилается на переднем плане вокруг недвижного пруда: подстриженные сосны, ивы, каменные фонари и резная статуя льва на постаменте у левого края. Фигуры в одеяниях прогуливаются по гравийным дорожкам по двое и по трое, а позади башни в дымке поднимаются лесистые холмы. Сцена спокойна и зелена, мягкий дневной свет лежит на воде, и Фарфоровая пагода стоит тёмным силуэтом на фоне бледного неба."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PRORA_RESORT"] =
    "Монолитный корпус курорта тянется вдоль берега, кажется, без конца. Его бледный фасад снова и снова несёт одни и те же ряды окон, простираясь вдоль пляжа, пока не исчезает у горизонта. Самый дальний отрезок ещё затянут строительными лесами. На ближнем конце стоит огромный круглый барабан здания, опоясанный колоннами на тёмно-красном основании, с красным флагом, реющим над крышей. Внизу пляж оживлён: купальщики и гуляющие рассыпаны мелкими фигурами по песку, а справа накатывает серо-зелёное море. Высокие залитые солнцем облака заполняют небо над ярким приморским днём, кремовый бетон на фоне синей воды."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_PYRAMID"] =
    "Две великие пирамиды стоят бледными в пустынной дымке, ближняя заполняет верхнюю правую часть кадра. Третья кажется маленькой на горизонте. Между ними в среднем плане припал Сфинкс. Тонкой линией вдоль песка стоят пальмы, а низкие разрушенные стены и каменные блоки окаймляют ложбину на переднем плане. Всадник в красном сидит на верблюде в нижнем правом углу, а слева через песок движется небольшой караван верблюдов, и рядом идут фигуры. Всё цвета песка, рыжевато-коричневое и цвета кости под мглистым белым небом. Красный всадник - единственное резкое цветовое пятно."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_RED_FORT"] =
    "Крепость из густо-красного песчаника под штурмом: высокие стены и круглые бастионы заполняют кадр, белые купольные павильоны стоят вдоль зубчатых стен, на уступах растёт трава, а из пожаров внутри поднимаются столбы чёрного дыма. Защитники теснятся на зубцах над воротами. На переднем плане солдаты в доспехах и округлых шлемах напирают на стены, проходя мимо деревянной катапульты и её расчёта у левого края. Картина тяжела от красного камня и дыма, и единственное облегчение - белые павильоны и полоса бледного неба."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_SISTINE_CHAPEL"] =
    "Богослужение внутри капеллы, вид из толпы молящихся. Торцевая стена за алтарём от пола до потолка покрыта фреской Страшного суда, водоворотом фигур на синем фоне, а боковые стены ниже высоких арочных окон убраны расписными сценами и драпировками. Расписанный свод лишь чуть заходит в верх кадра. Духовенство в белом служит у алтаря при свете свечей, а кардиналы в алом заполняют передний план и скамьи вдоль стен. Их красный - самый сильный цвет в сумрачном интерьере. Тот скудный дневной свет, что есть, падает серым из окон на расписные стены."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_INTERNATIONAL_SPACE_STATION"] =
    "Решётчатая станция висит на орбите на фоне черноты космоса: длинная центральная ферма пересечена парами больших серо-синих солнечных крыльев, а в её середине собрана цепочка белых цилиндрических модулей и стыковочных узлов. У ближнего конца цепочки модулей пришвартован корабль, а под фермой плоско расходятся панели радиаторов. Позади неё в глубокой синеве изгибается Земля, и на её ночной стороне ярко светятся завитки облаков. В черноте сверху рассыпаны звёзды. Изображение чистое и фотографичное: белый металл, синяя планета и ни одной фигуры."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_STATUE_OF_LIBERTY"] =
    "Облачённая в одеяние медная фигура, выцветшая до бледно-зелёного, стоит на каменном пьедестале слева от оживлённой гавани, рука с факелом высоко поднята к небу с рваными облаками. Мимо неё проходит океанский лайнер начала двадцатого века, с чёрным корпусом и двумя красно-чёрными трубами, тянущими за собой угольный дым, а вдоль него по зыби пробиваются буксиры. Низкий и подёрнутый дымкой нью-йоркский горизонт лежит за водой справа. Сцена написана в морских серых и зелёных тонах, дым и облака сливаются. Бледно-зелёная статуя - самая чёткая форма во всём этом дыму и облаках."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_STONEHENGE"] =
    "Кольцо громадных стоячих камней, увенчанных перемычками, стоит на тёмной вересковой пустоши ночью и тепло светится изнутри от разведённых где-то внутри костров, словно идёт обряд. По звёздному небу над ним чертит след комета. На затенённом переднем плане из пустоши поднимаются разбросанные отдельные камни, а по равнине рассыпаны несколько небольших костров и неясные фигуры. Всё погружено в глубокую ночную синеву, кроме янтарного света, скопившегося у монумента."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_SYDNEY_OPERA_HOUSE"] =
    "Большие белые оболочки крыши в форме парусов вблизи заполняют правую часть кадра, перекрывая друг друга на фоне ярко-синего неба. Под ними виднеется стекло и тёмная каменная кладка основания здания. Чуть дальше у причала стоит большой белый круизный лайнер, а по зыби переднего плана режет воду стремительная моторная яхта. За искрящейся гаванью вдалеке слева стоят небоскрёбы Сиднея. День ясный и солнечный. Белые крыши и белые суда выделяются на тёмной сине-зелёной воде."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_TAJ_MAHAL"] =
    "Беломраморный мавзолей стоит прямо напротив в конце своего длинного сада, его большой центральный купол вздымается над нишей со стрельчатым входом. По обе стороны от большого купола сидят меньшие купольные павильоны, а на каждом углу платформы поднимается минарет. Сад тянется прямо к нему: узкий отражающий канал по центру в окружении мощёных дорожек, ряды тёмных кипарисов и низкие зелёные клумбы. Несколько маленьких фигур в одеяниях идут по дорожкам. Небо позади - мягкий закат персикового и золотого цвета, и мрамор перенимает эту окраску, белизна переходит в кремовый и розовый."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_TEMPLE_ARTEMIS"] =
    "Длинная мраморная колоннада под скульптурным фронтоном венчает возвышенность в глубине сцены, перед лестницей вознесена конная статуя, а вдоль подхода тёмной чередой стоят кипарисы. Широкая терраса перед ней полна жизни: фигуры в белых тогах и цветных одеяниях прогуливаются и торгуют, слева у корзин сидят на корточках продавцы, а в правом переднем плане совсем рядом проходят женщины под покрывалами. У левого края вид обрамляет красная колонна, а далеко внизу уходит зелёная долинная местность с рекой. Полуденное солнце пылает на белом мраморе и яркой ткани под синим небом, нагромождённым облаками."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_STATUE_ZEUS"] =
    "В храмовом зале восседающий на троне бог поднимается до потолка, весь в золоте и слоновой кости, бородатый и обнажённый по пояс, с одеянием на коленях. Одна рука держит над залом небольшую крылатую фигуру Победы, другая сжимает высокий скипетр. Его трон отделан золотом на фоне стены тёплого красного цвета, а по обеим сторонам зала маршируют ряды колонн, оставляя боковые проходы в тени. Молящиеся в бледных одеяниях собрались у ног статуи, и никто из них не достаёт ей до голеней. Вдоль стен горят небольшие огни. Свет падает откуда-то сверху, скапливаясь золотом на статуе, а зал вокруг неё остаётся тусклым."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_TERRACOTTA_ARMY"] =
    "Ряды глиняных воинов заполняют кадр от стены до стены, шеренга за шеренгой воинов в полный рост в доспешных кафтанах стоят по стойке смирно. Они уходят вглубь длинными коридорами между земляными перегородками. Каждый ряд тает всё глубже в яме, пока самые дальние не превращаются в одни лишь силуэты на фоне золотистого свечения, пробивающегося в глубине зала. Фигуры землисто-коричневые и серые, их плечи и шлемы окаймлены тёплым светом. Настроение безмолвное и необъятное, армия мёртвых, выстроенная во тьме."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_UNITED_NATIONS"] =
    "Вид с уровня улицы на площадь Организации Объединённых Наций. Плоская стеклянная плита башни Секретариата поднимается слева, над длинным низким размахом здания ассамблеи. Ряд флагштоков несёт флаги многих государств вдоль квартала. Площадь полна делегатов: мужчины и женщины в деловых костюмах вперемешку с национальной одеждой, в центре толпы фигура в белом одеянии и головном уборе стран Залива, группы задерживаются в разговоре по пути внутрь. У тротуара справа ждёт жёлтое такси, а за флагами поднимается нью-йоркский горизонт. Стоит поздний день, по мостовой ложатся длинные тени, а низкое солнце ловит стекло."
CivVAccess_Strings["TXT_KEY_CIVVACCESS_WONDERDESC_BUILDING_UFFIZI"] =
    "Два длинных крыла галереи обращены друг к другу через узкий двор, высокие ренессансные фасады из серого камня и кремовой штукатурки со статуями, стоящими в нишах над лоджией первого этажа. Двор уходит вглубь картины к арочному проёму в дальнем конце, а за ним на фоне неба виднеется башня. Внизу двор оживлён флорентийцами в длинных платьях и тёмных кафтанах, по центру на постаментах выставлены скульптуры, а в левом переднем плане установлен прилавок под красным навесом. Послеполуденное солнце косо падает с одной стороны, тепло освещая верхние этажи, тогда как лоджия внизу держит прохладную тень."
